import itertools, random
# Sprinkler-style BN: C -> S, C -> R, (S,R) -> W. Query P(C=1 | W=1).
pC = 0.5
pS = {1: 0.1, 0: 0.5}; pR = {1: 0.8, 0: 0.2}
pW = {(1, 1): 0.99, (1, 0): 0.9, (0, 1): 0.9, (0, 0): 0.0}
b = lambda p, v: p if v else 1 - p
def joint(c, s, r, w): return b(pC, c) * b(pS[c], s) * b(pR[c], r) * b(pW[(s, r)], w)
# exact by full enumeration
num = sum(joint(1, s, r, 1) for s, r in itertools.product([0, 1], repeat=2))
den = sum(joint(c, s, r, 1) for c, s, r in itertools.product([0, 1], repeat=3))
exact = num / den
# variable elimination: sum out S and R first -> factor f(C) for evidence W=1, then normalise
f = {c: b(pC, c) * sum(b(pS[c], s) * sum(b(pR[c], r) * pW[(s, r)] for r in (0, 1)) for s in (0, 1)) for c in (0, 1)}
ve = f[1] / (f[0] + f[1])
print('enumeration =', exact, ' VE =', ve, ' identical:', abs(exact - ve) < 1e-15)
def rejection(N, seed):
    rnd = random.Random(seed); acc = hit = 0
    for _ in range(N):
        c = rnd.random() < pC; s = rnd.random() < pS[c]; r = rnd.random() < pR[c]; w = rnd.random() < pW[(s, r)]
        if w: acc += 1; hit += c
    return hit / acc
def gibbs(N, seed, burn=1000):
    rnd = random.Random(seed); st = {'c': 1, 's': 1, 'r': 1}; hit = 0
    for t in range(N + burn):
        for v in ('c', 's', 'r'):
            p1 = joint(*[1 if k == v else st[k] for k in ('c', 's', 'r')], 1)
            p0 = joint(*[0 if k == v else st[k] for k in ('c', 's', 'r')], 1)
            st[v] = int(rnd.random() < p1 / (p0 + p1))
        if t >= burn: hit += st['c']
    return hit / N
for N in (100, 1000, 100000):
    print(N, 'rejection:', [round(rejection(N, s), 4) for s in (1, 2)], ' gibbs:', [round(gibbs(N, s), 4) for s in (1, 2)])
